(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-335":{scenario:{company:"Sóc Nâu English Online",supervisor:{name:"Đinh Thị Mai",role:{vi:"Trưởng nhóm Telesales",en:"Telesales Team Lead"}},ref_code:"OD-2217",title:{vi:"Đúng ưu đãi. Đúng số tiền. Đúng lời hứa.",en:"Right offer. Right amount. Honest promise."},brief:{vi:"Bạn kiểm tra đơn OD-2217 vừa chốt qua điện thoại: khách đã học gói 12 tháng năm trước, gói hết hạn cách đây 2 tháng, không có mã giới thiệu. Gói 12 tháng giá niêm yết 7200000 đồng. Ưu đãi mô phỏng: NEW30 giảm 30% chỉ cho khách chưa từng mua; RENEW15 giảm 15% cho khách cũ gia hạn trong 6 tháng sau hết hạn; REFER10 giảm 10% khi có mã giới thiệu. Khách trả góp 6 kỳ qua thẻ. Sửa mã ưu đãi và số tiền mỗi kỳ, rồi lập báo cáo có căn cứ.",en:"You are checking order OD-2217 closed by phone: the customer took the 12-month package last year, it expired 2 months ago, and there is no referral code. The 12-month package lists at 7200000 VND. Training offers: NEW30 gives 30% off for first-time buyers only; RENEW15 gives 15% off for returning customers renewing within 6 months of expiry; REFER10 gives 10% off with a referral code. The customer pays in 6 card installments. Correct the promo code and the installment amount, then write an evidence-based report."},reference_title:{vi:"Chính sách ưu đãi & bảng tính trả góp đã duyệt · OD-2217",en:"Approved offer policy & installment sheet · OD-2217"},fields:[{id:"PROMO_CODE",label:{vi:"Mã ưu đãi áp dụng",en:"Applied promo code"},initial:"NEW30",expected:"RENEW15",choices:["NEW30","RENEW15","REFER10"],reference:"Chính sách ưu đãi tháng",hint:{vi:"Tra lịch sử mua của khách trên CRM rồi đối chiếu điều kiện đối tượng của từng mã.",en:"Check the customer's purchase history in the CRM and match each code's eligibility."}},{id:"INSTALL_AMT",label:{vi:"Số tiền mỗi kỳ trả góp (VND)",en:"Amount per installment (VND)"},initial:"840000",expected:"1050600",reference:"Bảng tính trả góp",ref_value:{vi:"Giá niêm yết 7200000 đồng; khách cũ hết hạn 2 tháng; trả góp 6 kỳ qua thẻ",en:"List price 7200000 VND; returning customer expired 2 months ago; 6 card installments"},hint:{vi:"Bản nháp dùng sai tỷ lệ ưu đãi và quên phí chuyển đổi trả góp.",en:"The draft uses the wrong discount rate and forgets the installment conversion fee."}}],sop32:{vi:"Số tiền mỗi kỳ = giá niêm yết x (1 - tỷ lệ ưu đãi hợp lệ) x (1 + phí chuyển đổi trả góp 3%) / số kỳ. Phí 3% là số liệu mô phỏng và phải được báo rõ cho khách trước khi chốt.",en:"Amount per installment = list price x (1 - valid discount) x (1 + 3% installment conversion fee) / number of installments. The 3% fee is a training figure and must be disclosed before closing."},context:{label:"CRM-CALL / OD-2217",metrics:[{label:{vi:"Giá niêm yết gói 12 tháng",en:"12-month list price"},value:"7,200,000 VND"},{label:{vi:"Số kỳ trả góp",en:"Installments"},value:"6"},{label:{vi:"Phí chuyển đổi mô phỏng",en:"Training conversion fee"},value:"3%"},{label:{vi:"Số tháng từ khi hết hạn",en:"Months since expiry"},value:"2"}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn cả nhóm: “Cuối tháng rồi, cứ nói với khách là học xong cam kết đầu ra IELTS 7.0, không đạt hoàn 100%, và ưu đãi chỉ còn hôm nay dù chương trình kéo dài đến cuối tháng.”",en:"The sales director messages the team: “It is month end. Tell customers we guarantee an IELTS 7.0 result or a 100% refund, and that the offer ends today even though it runs to month end.”"},options:{safe:{vi:"Từ chối hứa đầu ra và tạo khan hiếm giả; chỉ dùng kịch bản, chính sách hoàn tiền đã duyệt, báo Trưởng nhóm và bộ phận kiểm soát chất lượng cuộc gọi; đề xuất mời khách học thử, kiểm tra trình độ.",en:"Refuse the outcome guarantee and fake urgency; use only the approved script and refund policy, inform the team lead and call QA; propose a trial class and placement test."},shortcut:{vi:"Nói theo chỉ đạo cho kịp chỉ tiêu, nếu khách khiếu nại thì để bộ phận chăm sóc xử lý.",en:"Say it as instructed to hit the target and let customer care deal with complaints."},wait:{vi:"Tạm ngừng gọi, không phản hồi và chờ xem đồng nghiệp làm thế nào.",en:"Stop calling, give no reply and wait to see what colleagues do."}},questions:{vi:["Vì sao đơn OD-2217 phải dùng RENEW15 thay vì NEW30 hay REFER10? Dữ liệu CRM nào chứng minh?","Trình bày cách tính số tiền mỗi kỳ và rủi ro khi hứa cam kết đầu ra hoặc tạo khan hiếm giả qua điện thoại."],en:["Why must order OD-2217 use RENEW15 instead of NEW30 or REFER10? Which CRM data proves it?","Explain the installment calculation and the risk of promising guaranteed results or fake urgency by phone."]},hints:{vi:["Đặt bản nháp cạnh chính sách ưu đãi, kiểm tra khách thuộc nhóm đối tượng nào và có mã giới thiệu không.","Tính theo SOP mục 3.2: ưu đãi trước, cộng phí chuyển đổi rồi chia đều cho số kỳ.","Đọc lại SOP mục 4.2: không đưa thông tin gian dối cho khách; chỉ đạo sai phải được báo cáo."],en:["Place the draft next to the offer policy and check the customer's segment and referral status.","Compute per SOP 3.2: discount first, add the conversion fee, then divide by the installments.","Re-read SOP 4.2: never give customers false information; wrong instructions must be escalated."]}},learning:{summary:{vi:"Chuyên viên bán hàng qua điện thoại (inside sales, telesales) tư vấn và chốt đơn từ xa qua cuộc gọi, tin nhắn, video: gọi danh sách khách hàng tiềm năng hợp lệ, khai thác nhu cầu, giới thiệu sản phẩm phù hợp, xử lý từ chối, áp dụng đúng ưu đãi và hoàn tất đơn hàng trên CRM. Nghề đòi hỏi giọng nói rõ ràng, kỹ năng đặt câu hỏi, tính giá chính xác, chịu áp lực chỉ tiêu và tuân thủ nghiêm quy định về cuộc gọi quảng cáo, dữ liệu cá nhân và quyền lợi người tiêu dùng.",en:"An inside sales or telesales executive advises and closes deals remotely by call, message and video: calling lawful prospect lists, discovering needs, presenting the right product, handling objections, applying the correct offer and completing the order in the CRM. The role needs a clear voice, questioning skills, accurate pricing, resilience under targets and strict compliance with marketing call, personal data and consumer protection rules."},responsibilities:{vi:["Gọi danh sách khách hàng tiềm năng có nguồn hợp lệ, loại bỏ số đã đăng ký không nhận quảng cáo.","Khai thác nhu cầu và tư vấn gói phù hợp theo kịch bản, chính sách đã duyệt.","Áp dụng đúng mã ưu đãi, tính giá, trả góp và xác nhận lại điều khoản trước khi chốt.","Ghi kết quả cuộc gọi, mã trạng thái và lịch gọi lại đầy đủ trên CRM.","Phối hợp chăm sóc khách sau bán và báo cáo tỷ lệ chuyển đổi hằng ngày."],en:["Call lawfully sourced prospect lists and remove numbers registered as do-not-call.","Discover needs and recommend the right package using the approved script and policy.","Apply the correct promo code, price and installments and confirm terms before closing.","Log call results, disposition codes and callbacks fully in the CRM.","Coordinate after-sales care and report daily conversion rates."]},competencies:[{name:{vi:"Giao tiếp qua giọng nói",en:"Voice communication"},desc:{vi:"Mở lời tự tin, nói rõ, nhịp độ phù hợp và tạo thiện cảm trong 30 giây đầu.",en:"Open confidently, speak clearly at the right pace and build rapport in 30 seconds."}},{name:{vi:"Khai thác nhu cầu",en:"Needs discovery"},desc:{vi:"Dùng câu hỏi mở, kỹ thuật SPIN để hiểu mục tiêu, khó khăn và khả năng chi trả.",en:"Use open and SPIN questions to understand goals, pain points and budget."}},{name:{vi:"Xử lý từ chối",en:"Objection handling"},desc:{vi:"Lắng nghe, xác nhận, trả lời bằng giá trị thật và kiểm tra lại mối quan tâm của khách.",en:"Listen, acknowledge, answer with real value and check the concern again."}},{name:{vi:"Chính xác giá & điều khoản",en:"Price & terms accuracy"},desc:{vi:"Áp đúng ưu đãi, phí trả góp và đọc lại tổng chi phí cho khách trước khi chốt.",en:"Apply the right offer and fees and read back the total cost before closing."}},{name:{vi:"Tuân thủ & trung thực",en:"Compliance & honesty"},desc:{vi:"Không hứa sai sự thật, không tạo khan hiếm giả, tôn trọng yêu cầu ngừng liên hệ.",en:"No false promises or fake urgency, and respect requests to stop contact."}}],knowledge:{vi:["Nghị định 91/2020/NĐ-CP về chống tin nhắn rác, thư điện tử rác, cuộc gọi rác: danh sách không quảng cáo, khung giờ và tần suất gọi theo quy định.","Luật Bảo vệ quyền lợi người tiêu dùng 2023: giao dịch từ xa, nghĩa vụ cung cấp thông tin trung thực, cấm thông tin gian dối.","Quy định về bảo vệ dữ liệu cá nhân: nguồn dữ liệu hợp pháp, sự đồng ý và quyền phản đối tiếp thị của khách.","Kỹ thuật bán hàng tư vấn SPIN (Tình huống, Vấn đề, Hệ quả, Lợi ích) và mô hình xử lý từ chối.","Cách tính ưu đãi, trả góp, phí chuyển đổi và nghĩa vụ công bố đầy đủ chi phí cho khách."],en:["Decree 91/2020/ND-CP on spam messages, emails and calls: do-not-call list and regulated calling hours and frequency.","Consumer Protection Law 2023: remote transactions, the duty to give truthful information and the ban on deceptive claims.","Personal data protection rules: lawful data sources, consent and the customer's right to object to marketing.","SPIN consultative selling (Situation, Problem, Implication, Need-payoff) and objection handling models.","Calculating discounts, installments and conversion fees and the duty to disclose all costs."]},tools:["Tổng đài VoIP / auto dialer","Hệ thống CRM","Kịch bản cuộc gọi số hóa","Công cụ ghi âm & chấm điểm cuộc gọi","Cổng thanh toán và trả góp"],kpis:{vi:["Tỷ lệ chuyển đổi từ cuộc gọi kết nối sang đơn hàng.","Doanh thu chốt mỗi ngày và mỗi giờ gọi.","Tỷ lệ đơn hủy, hoàn tiền do tư vấn sai (mục tiêu bằng 0).","Điểm kiểm soát chất lượng cuộc gọi về tuân thủ kịch bản."],en:["Conversion rate from connected calls to orders.","Revenue closed per day and per calling hour.","Cancellations or refunds caused by wrong advice (target zero).","Call QA score for script compliance."]},day:[{time:"08:15",vi:"Họp đầu ca, cập nhật ưu đãi đang chạy và danh sách gọi đã lọc số từ chối.",en:"Shift huddle on current offers and the call list cleaned of opt-outs."},{time:"08:30",vi:"Gọi khung giờ sáng cho khách mới và khách cũ sắp hết hạn gói.",en:"Morning calling block for new prospects and customers near expiry."},{time:"13:30",vi:"Gọi lại theo lịch hẹn, tư vấn chi tiết và gửi đường dẫn thanh toán.",en:"Scheduled callbacks, detailed advice and sending payment links."},{time:"15:30",vi:"Rà soát đơn đã chốt: mã ưu đãi, số tiền trả góp, xác nhận thanh toán.",en:"Review closed orders: promo codes, installment amounts and payment confirmation."},{time:"17:30",vi:"Nghe lại cuộc gọi cùng bộ phận chất lượng và báo cáo kết quả ngày.",en:"Review recorded calls with QA and report the day's results."}],mistakes:{vi:["Áp mã ưu đãi cho sai đối tượng khiến đơn bị điều chỉnh, khách mất niềm tin.","Báo số tiền trả góp mà quên phí chuyển đổi, khách khiếu nại sau khi thanh toán.","Hứa cam kết kết quả, tạo khan hiếm giả hoặc tiếp tục gọi số đã từ chối."],en:["Applying an offer to the wrong segment so the order must be corrected and trust is lost.","Quoting installments without the conversion fee, leading to complaints after payment.","Promising guaranteed results, faking urgency or calling numbers that opted out."]},career:[{vi:"Nhân viên telesales",en:"Telesales agent"},{vi:"Chuyên viên inside sales",en:"Inside sales executive"},{vi:"Trưởng nhóm telesales",en:"Telesales team lead"},{vi:"Quản lý trung tâm bán hàng từ xa",en:"Remote sales center manager"}],glossary:[{term:"Call disposition",vi:"Mã trạng thái kết quả cuộc gọi như quan tâm, gọi lại, không nghe máy, từ chối liên hệ.",en:"A call outcome code such as interested, callback, no answer or do not call."},{term:"DNC",vi:"Danh sách không nhận cuộc gọi quảng cáo; số trong danh sách phải được loại khỏi chiến dịch.",en:"Do-not-call list; listed numbers must be removed from campaigns."},{term:"Conversion rate",vi:"Tỷ lệ cuộc gọi kết nối hoặc khách tiềm năng chuyển thành đơn hàng.",en:"Share of connected calls or prospects that become orders."},{term:"SPIN",vi:"Kỹ thuật đặt câu hỏi theo Tình huống, Vấn đề, Hệ quả, Lợi ích mong muốn.",en:"Questioning on Situation, Problem, Implication and Need-payoff."},{term:"Call QA",vi:"Chấm điểm chất lượng cuộc gọi theo tiêu chí kịch bản, thái độ và tuân thủ.",en:"Scoring recorded calls on script, attitude and compliance criteria."}],quiz:[{q:{vi:"Gói 6000000 đồng, ưu đãi 15%, phí chuyển đổi trả góp 2%, trả 3 kỳ. Số tiền mỗi kỳ là bao nhiêu?",en:"A 6000000 VND package, 15% off, 2% conversion fee, 3 installments. What is each installment?"},options:{vi:["1700000 đồng","1734000 đồng","2000000 đồng","1445000 đồng"],en:["1700000 VND","1734000 VND","2000000 VND","1445000 VND"]},answer:1,explain:{vi:"6000000 x 85% = 5100000; x 1,02 = 5202000; chia 3 kỳ = 1734000 đồng.",en:"6000000 x 85% = 5100000; x 1.02 = 5202000; divided by 3 = 1734000 VND."}},{q:{vi:"Khách cũ hết hạn gói 4 tháng, không có mã giới thiệu. Theo chính sách trong bài, mã nào hợp lệ?",en:"A returning customer expired 4 months ago with no referral code. Under the training policy, which code is valid?"},options:{vi:["NEW30","REFER10","RENEW15","Không mã nào"],en:["NEW30","REFER10","RENEW15","None"]},answer:2,explain:{vi:"RENEW15 dành cho khách cũ gia hạn trong 6 tháng sau hết hạn; NEW30 chỉ cho khách chưa từng mua.",en:"RENEW15 is for returning customers within 6 months of expiry; NEW30 is for first-time buyers only."}},{q:{vi:"Cấp trên yêu cầu hứa cam kết đầu ra và nói ưu đãi chỉ còn hôm nay dù không đúng. Bạn làm gì?",en:"A manager tells you to promise guaranteed results and say the offer ends today when it does not. What do you do?"},options:{vi:["Từ chối, chỉ dùng thông tin đã duyệt và báo trưởng nhóm, bộ phận chất lượng","Làm theo vì là chỉ đạo","Chỉ nói với khách có vẻ dễ chốt","Nói nhưng không ghi vào CRM"],en:["Refuse, use only approved information and report to the team lead and QA","Comply because it is an instruction","Say it only to easy prospects","Say it but keep it out of the CRM"]},answer:0,explain:{vi:"Thông tin gian dối, khan hiếm giả vi phạm quyền lợi người tiêu dùng và dẫn tới khiếu nại, hoàn tiền, xử phạt.",en:"False claims and fake urgency breach consumer rights and lead to complaints, refunds and penalties."}},{q:{vi:"Khách nói “đừng gọi cho tôi nữa”. Mã trạng thái cuộc gọi đúng là gì?",en:"The customer says “do not call me again”. What is the correct disposition?"},options:{vi:["CALLBACK","NO-ANSWER","INTERESTED","DNC, ghi nhận từ chối và ngừng liên hệ"],en:["CALLBACK","NO-ANSWER","INTERESTED","DNC, record the opt-out and stop contact"]},answer:3,explain:{vi:"Yêu cầu ngừng liên hệ phải được ghi nhận ngay và áp dụng cho mọi chiến dịch sau.",en:"An opt-out must be recorded at once and applied to all later campaigns."}}],tools_en:["VoIP PBX / auto dialer","CRM system","Digital call scripts","Call recording & scoring tool","Payment and installment gateway"]}}})})(window.KKR);
